        el.title = posLabel(pos);
        el.setAttribute('aria-label', 'Load ' + CARDS[cardIdx].name + ' in Finder, ' + posLabel(pos));
        const spiritualPos = spir.indexOf(cardIdx);
        const code = binaryScript(spiritualPos);
        const decimal = el.querySelector('.sl-card-binary-decimal');
        decimal.textContent = String(parseInt(code, 2));
        decimal.setAttribute('aria-label', 'Decimal ' + decimal.textContent);
        const reverseDecimal = el.querySelector('.sl-card-binary-reverse');
        reverseDecimal.textContent = String(parseInt(code.split('').reverse().join(''), 2));
        reverseDecimal.setAttribute('aria-label', 'Reversed binary decimal ' + reverseDecimal.textContent);
        const bit = el.querySelector('.sl-card-binary-bit');
