// NatureCities API: resolve(text) -> {label, zone, latitude, longitude} or null.
// Data injected by the packager from GeoNames (CC BY 4.0); major cities/capitals
// and Australian cities in the cities15000 dataset. No network requests.
(function () {
  'use strict';
  const cities = window.NATURE_CITY_DATA;
  const normalize = text => String(text || '').trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const exact = new Map(), names = new Map();
  cities.forEach(function (city) {
    exact.set(normalize(city[0]), city);
    [city[4], city[5]].forEach(function (name) {
      const key = normalize(name);
      if (!names.has(key)) names.set(key, city);
      else if (names.get(key) !== city) names.set(key, null);
    });
  });
  window.NatureCities = {
    resolve(text) {
      const city = exact.get(normalize(text)) || names.get(normalize(text));
      return city ? { label: city[0], zone: city[1], latitude: city[2], longitude: city[3] } : null;
    },
    count: cities.length
  };
  document.addEventListener('DOMContentLoaded', function () {
    const list = document.getElementById('ncBirthCities');
    if (!list) return;
    const options = document.createDocumentFragment();
    cities.forEach(function (city) {
      const option = document.createElement('option');
      option.value = city[0]; option.label = city[1];
      options.appendChild(option);
    });
    list.appendChild(options);
  });
})();

