// Portable Finder disclosure controls. No public APIs; keeps state across rerenders.
(function () {
  'use strict';
  const expanded = new Map();
  let serial = 0;
  function enhance(root) {
    root.querySelectorAll('#fAboutDates .ls-stat-block, #fAboutCardology .ls-stat-block, #fAboutDisplacements .ls-stat-block, #fAboutPersonality, #fAboutLongform, #fInTime, #fAboutModern > .ls-zodiac-block, #ncAlternateResult, .ls-connections-wrap').forEach(function (section) {
      let heading = Array.from(section.children).find(function (child) {
        return child.matches('.ls-stat-label, .finder-about-subtitle, h3, h4, h5');
      });
      const nestedHeading = section.querySelector(':scope > .ls-zodiac-heading > .ls-stat-label, :scope > .nc-connections-header > .ls-stat-label');
      const label = heading || nestedHeading;
      if (!label || label.querySelector('.nc-fold-toggle')) return;
      heading = label;
      const headingGroup = heading.parentElement === section ? heading : heading.parentElement;
      const title = heading.textContent.trim();
      if (!title) return;
      const key = title;
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'nc-fold-toggle';
      button.textContent = title;
      const body = document.createElement('div');
      body.className = 'nc-fold-body';
      body.id = 'nc-fold-' + (++serial);
      button.setAttribute('aria-controls', body.id);
      // Keep original headings and classes so the reading modules can find them.
      heading.replaceChildren(button);
      Array.from(section.childNodes).forEach(function (child) {
        if (child !== headingGroup) body.appendChild(child);
      });
      section.appendChild(body);
      function setOpen(open) {
        expanded.set(key, open);
        button.setAttribute('aria-expanded', String(open));
        body.hidden = !open;
        body.inert = !open;
      }
      setOpen(expanded.has(key) ? expanded.get(key) : true);
      button.addEventListener('click', function () {
        setOpen(button.getAttribute('aria-expanded') !== 'true');
      });
    });
  }
  document.addEventListener('DOMContentLoaded', function () {
    const root = document.getElementById('fAboutModern');
    if (!root) return;
    enhance(root);
    new MutationObserver(function () { enhance(root); }).observe(root, { childList: true, subtree: true });
  });
})();

